func (cm *ConnManager) handleFailedConn(c *ConnReq) {
	if atomic.LoadInt32(&cm.stop) != 0 {
		return
	}
	if c.Permanent {
		c.retryCount++
		d := time.Duration(c.retryCount) * cm.cfg.RetryDuration
		if d > maxRetryDuration {
			d = maxRetryDuration
		}
		cm.log.Debug().Msgf("Retrying connection to %v in %v", c, d)
		time.AfterFunc(d, func() {
			cm.Connect(c)
		})
	} else if cm.cfg.GetNewAddress != nil {
		if cm.registerFailedConnectionTo(c) {
			return
		}
		go cm.NewConnReq()
	}
}

// registerFailedConnectionTo registers a failed connection attempt to the given address or globally.
// It returns true if further action (such as trying to connect again immediately) should be stopped.
func (cm *ConnManager) registerFailedConnectionTo(c *ConnReq) bool {
	if c.Addr != nil && c.Addr.String() != "" && cm.cfg.BanAddress != nil {
		cm.incAddrConnAttempt(c.Addr.String())
		if cm.getAddrConnAttempt(c.Addr.String()) >= maxFailedAttempts {
			cm.cfg.BanAddress(c.Addr.String())
			return true
		}
	} else {
		cm.incGlobalFailedAttempts()
		if cm.getGlobalFailedAttempts() >= maxFailedAttempts {
			cm.log.Debug().Msgf("Max failed connection attempts reached: [%d] "+
				"-- retrying connection in: %v", maxFailedAttempts,
				cm.cfg.RetryDuration)
			time.AfterFunc(cm.cfg.RetryDuration, func() {
				cm.NewConnReq()
			})
			return true
		}
	}
	return false
}

